for _ in range(int(input())):
	(n, m) = map(int, input().split())
	A = [[x for x in input().split()] for __ in range(n)]
	res = 'FINE'
	for i in A:
		if i[0] == 'correct' and i[1].count('0') > 0:
			res = 'INVALID'
			break
		elif i[0] == 'wrong' and i[1].count('1') == m:
			res = 'WEAK'
	print(res)
